//! DOM Interface WrapperTypeInfo Definitions
//!
//! This module defines WrapperTypeInfo for core DOM interfaces.
//! Eventually these will be generated by codegen, but for now they're
//! manually defined to enable type-safe V8 bindings.
//!
//! ## Tag Assignment
//!
//! Tags are assigned to form contiguous ranges for inheritance checking:
//!
//! ```
//! EventTarget (100, max: 899)
//!   └─ Node (110, max: 889)
//!       ├─ Element (120, max: 599)
//!       │   └─ HTMLElement (130, max: 500)
//!       │       ├─ HTMLDivElement (140)
//!       │       ├─ HTMLSpanElement (141)
//!       │       └─ ... other HTML elements
//!       ├─ CharacterData (600, max: 650)
//!       │   ├─ Text (610)
//!       │   │   └─ CDATASection (611)
//!       │   ├─ Comment (620)
//!       │   └─ ProcessingInstruction (621)
//!       ├─ DocumentFragment (700, max: 750)
//!       │   └─ ShadowRoot (710)
//!       ├─ DocumentType (800)
//!       └─ Document (810, max: 850)
//!           ├─ HTMLDocument (820)
//!           └─ XMLDocument (821)
//! ```

const std = @import("std");
const wrapper_type_info = @import("wrapper_type_info.zig");
const WrapperTypeInfo = wrapper_type_info.WrapperTypeInfo;
const TypeTag = wrapper_type_info.TypeTag;
const WrapperClassId = wrapper_type_info.WrapperClassId;
const IdlDefinitionKind = wrapper_type_info.IdlDefinitionKind;
const v8 = @import("ffi.zig");

// ============================================================================
// Placeholder install functions (these would normally be generated)
// ============================================================================

fn placeholderInstall(_: *v8.Isolate) *v8.FunctionTemplate {
    // INTENTIONAL PANIC: This is a placeholder for codegen-generated implementations.
    // If this code path is reached, it means:
    // 1. Code is trying to use a DOM interface before codegen has run
    // 2. Or the interface is being used but its template hasn't been generated yet
    //
    // This is a programming error, not a runtime error that should be recoverable.
    // The correct fix is to run codegen to generate the real implementations.
    //
    // Note: We use @panic here instead of unreachable because unreachable in
    // ReleaseFast is undefined behavior, while @panic always produces a crash
    // with a clear message.
    @panic("WrapperTypeInfo.install_template_fn called but not implemented - run codegen to generate implementations");
}

// ============================================================================
// EventTarget hierarchy
// ============================================================================

pub const EventTarget_type_info = WrapperTypeInfo{
    .interface_name = "EventTarget",
    .parent = null,
    .this_tag = 100,
    .max_subclass_tag = 899, // Covers Node, Window, and all descendants
    .wrapper_class_id = .object,
    .idl_definition_kind = .interface,
    .install_template_fn = placeholderInstall,
};

// ============================================================================
// Window (Global object) - inherits from EventTarget
// ============================================================================

pub const Window_type_info = WrapperTypeInfo{
    .interface_name = "Window",
    .parent = &EventTarget_type_info,
    .this_tag = 105, // Between EventTarget (100) and Node (110)
    .max_subclass_tag = 105, // Leaf node (no subclasses)
    .wrapper_class_id = .object,
    .idl_definition_kind = .interface,
    .install_template_fn = placeholderInstall,
};

