// ============================================================================
// Helper functions
// ============================================================================

/// Get WrapperTypeInfo by interface name
pub fn getTypeInfoByName(name: []const u8) ?*const WrapperTypeInfo {
    const type_infos = [_]*const WrapperTypeInfo{
        &EventTarget_type_info,
        &Window_type_info,
        &Node_type_info,
        &Element_type_info,
        &HTMLElement_type_info,
        &HTMLDivElement_type_info,
        &HTMLSpanElement_type_info,
        &CharacterData_type_info,
        &Text_type_info,
        &CDATASection_type_info,
        &Comment_type_info,
        &ProcessingInstruction_type_info,
        &DocumentFragment_type_info,
        &ShadowRoot_type_info,
        &DocumentType_type_info,
        &Document_type_info,
        &HTMLDocument_type_info,
        &XMLDocument_type_info,
        &Event_type_info,
        &CustomEvent_type_info,
        &URL_type_info,
        &URLSearchParams_type_info,
        &MessagePort_type_info,
        &MessageChannel_type_info,
    };

    for (type_infos) |info| {
        if (std.mem.eql(u8, info.getName(), name)) {
            return info;
        }
    }
    return null;
}

// ============================================================================
// Tests
// ============================================================================

test "DOM type info hierarchy" {
    const testing = std.testing;

    // Test inheritance chain
    try testing.expect(HTMLDivElement_type_info.isSubclassOf(&HTMLElement_type_info));
    try testing.expect(HTMLDivElement_type_info.isSubclassOf(&Element_type_info));
    try testing.expect(HTMLDivElement_type_info.isSubclassOf(&Node_type_info));
    try testing.expect(HTMLDivElement_type_info.isSubclassOf(&EventTarget_type_info));

    // Test non-inheritance
    try testing.expect(!Element_type_info.isSubclassOf(&Document_type_info));
    try testing.expect(!Event_type_info.isSubclassOf(&Node_type_info));
}

test "DOM type info tag ranges" {
    const testing = std.testing;

    // Test tag range checking
    // Node should accept Element, Document, Text, etc.
    try testing.expect(Node_type_info.isValidTag(Element_type_info.this_tag));
    try testing.expect(Node_type_info.isValidTag(Document_type_info.this_tag));
    try testing.expect(Node_type_info.isValidTag(Text_type_info.this_tag));

    // EventTarget should accept Node and all descendants
    try testing.expect(EventTarget_type_info.isValidTag(Node_type_info.this_tag));
    try testing.expect(EventTarget_type_info.isValidTag(HTMLDivElement_type_info.this_tag));

    // But Node should NOT accept Event (outside its range)
    try testing.expect(!Node_type_info.isValidTag(Event_type_info.this_tag));
}

test "getTypeInfoByName" {
    const testing = std.testing;

    const element_info = getTypeInfoByName("Element");
    try testing.expect(element_info != null);
    try testing.expectEqual(@as(TypeTag, 120), element_info.?.this_tag);

    const unknown = getTypeInfoByName("Unknown");
    try testing.expect(unknown == null);
}
